function validate([n, w, maxWeight]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is an integer from 1 to 1000.';
  if (!Number.isInteger(w) || w < 1 || w > 1000) return 'w is an integer from 1 to 1000.';
  if (!Number.isInteger(maxWeight) || maxWeight < 1 || maxWeight > 1e9) return 'maxWeight is an integer from 1 to 10^9.';
  return null;
}

