function maxContainers(n, w, maxWeight) {
  // Fill the deck cell by cell and stop when the next container would be too heavy.
  let count = 0;
  let load = 0;
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      if (load + w > maxWeight) return count;
      load += w;
      count++;
    }
  }
  return count;
}

