function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(900, 1000);
    const w = pick(1, 1000);
    // Aim near the full deck's weight so either limit can be the one that binds.
    const full = n * n * w;
    const maxWeight = Math.min(1e9, Math.max(1, pick(Math.floor(full / 2), full + w)));
    return [n, w, maxWeight];
  }
  const n = pick(1, 6);
  const w = pick(1, 12);
  const roll = rand();
  let maxWeight;
  if (roll < 0.15) maxWeight = pick(1, w);
  else if (roll < 0.3) maxWeight = n * n * w + pick(-1, 1);
  else maxWeight = pick(1, n * n * w + 3 * w);
  return [n, w, Math.max(1, maxWeight)];
}
